db()->beginTransaction();
try {
 foreach ([['Green Warriors Cricket','Cricket','From the nets to match day. Build your technique and represent our campus together.','Kasun Perera','Main cricket ground',50],['NSBM Football Club','Football','Find your rhythm, build your team, and take your game to the next level. All abilities welcome.','Dilan Silva','Football ground',40],['Campus Basketball','Basketball','Fast breaks, new friendships, and a shared love of the game. Join our weekly court sessions.','Nimali Fernando','Indoor sports complex',35],['Athletics Collective','Athletics','Chase your personal best with a supportive community of sprinters and distance runners.','Amal Jayasinghe','Athletics track',60]] as $c) query('INSERT INTO clubs(name,sport,description,coach,location,capacity) VALUES(?,?,?,?,?,?)',$c);
 $clubs=rows('SELECT id,name FROM clubs ORDER BY id');
 foreach ([['Inter-Faculty Football Championship','Football','Represent your faculty in our campus football championship. Individual registrations are assigned by the sports office.','Football ground',10,11,8,64],['Green University Cricket Cup','Cricket','A campus cricket celebration. Join the player roster and compete for your faculty.','Main cricket ground',16,18,14,48],['Three-on-Three Basketball','Basketball','Bring your energy to a weekend of basketball and campus community.','Indoor sports complex',23,24,20,36]] as [$name,$sport,$desc,$loc,$start,$end,$deadline,$capacity]) query('INSERT INTO tournaments(name,sport,description,location,starts_at,ends_at,registration_deadline,capacity) VALUES(?,?,?,?,?,?,?,?)',[$name,$sport,$desc,$loc,date('Y-m-d 09:00:00',strtotime("+$start days")),date('Y-m-d 18:00:00',strtotime("+$end days")),date('Y-m-d 23:59:00',strtotime("+$deadline days")),$capacity]);
 foreach ($clubs as $i=>$c) query('INSERT INTO events(club_id,title,kind,location,starts_at,ends_at) VALUES(?,?,"training",?,?,?)',[$c['id'],$c['name'].' · Open training','Campus sports grounds',date('Y-m-d 16:00:00',strtotime('+'.($i+2).' days')),date('Y-m-d 18:00:00',strtotime('+'.($i+2).' days'))]);
 query('INSERT INTO events(club_id,title,kind,location,starts_at,ends_at,opponent) VALUES(?,?,"match",?,?,?,?)',[$clubs[0]['id'],'Inter-University Friendly','Main cricket ground',date('Y-m-d 09:00:00',strtotime('+7 days')),date('Y-m-d 15:00:00',strtotime('+7 days')),'Visiting University XI']);
 query('INSERT INTO events(club_id,title,kind,location,starts_at,ends_at,opponent,home_score,away_score) VALUES(?,?,"match",?,?,?,?,?,?)',[$clubs[1]['id'],'Campus Football Friendly','Football ground',date('Y-m-d 16:00:00',strtotime('-3 days')),date('Y-m-d 18:00:00',strtotime('-3 days')),'Alumni FC',3,1]);
 foreach ([['Indoor Sports Court','facility','A versatile court for basketball, badminton, and team training.','Indoor sports complex'],['Athletics Track','facility','Outdoor track for running practice and athletics sessions.','Campus grounds'],['Cricket Practice Kit','equipment','Practice bats, protective pads, and training balls.','Sports office'],['Football Training Kit','equipment','Training balls, cones, and team bibs.','Sports office']] as $r) query('INSERT INTO resources(name,kind,description,location) VALUES(?,?,?,?)',$r);
 db()->commit(); echo "Demo sports data created. No demo users or shared passwords were created.\n";
} catch (Throwable $e) { db()->rollBack(); throw $e; }
